design.prefetcher_source:
#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_default_s0 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    uint64_t last_addr = 0;
    int64_t stride = 0;

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                       uint8_t cache_hit, bool useful_prefetch,
                                       access_type type, uint32_t metadata_in) {
        if (last_addr != 0) {
            int64_t new_stride = static_cast<int64_t>(addr) - static_cast<int64_t>(last_addr);
            if (new_stride == stride) {
                champsim::address pf_addr(static_cast<uint64_t>(static_cast<int64_t>(addr) + stride));
                prefetch_line(pf_addr, false, 0);
            }
            stride = new_stride;
        }
        last_addr = addr;
        return metadata_in;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                    uint8_t prefetch, champsim::address evicted_addr,
                                    uint32_t metadata_in) {
        return metadata_in;
    }
};

